with p as (select id from liq_proveedores where nombre='Bank of America')
update liq_proveedores set email_patron='nombre.apellido@bofa.com', email_patron_fuente='https://newsroom.bankofamerica.com/content/newsroom/journalist-resources/bank-of-america-media-contacts (Verificación 19-oct-2026 vía resultados de búsqueda: la página de contactos de prensa publica andrew.aldridge@bofa.com y melissa.anchan@bofa.com; jerome.f.dubrowski@bofa.com aparece como contacto de prensa en comunicados de resultados 2020-2022 y en BusinessWire. Patrón respaldado por direcciones reales publicadas, pero no es determinista: algunos empleados llevan inicial intermedia.) · confianza: media',
 canales_publicos='[{"canal": "Newsroom oficial - contactos de prensa (derivación interna)", "valor": "https://newsroom.bankofamerica.com/content/newsroom/journalist-resources/bank-of-america-media-contacts", "fuente": "https://newsroom.bankofamerica.com/content/newsroom/journalist-resources/bank-of-america-media-contacts"}, {"canal": "Anuncio oficial consorcio The Clearing House (depósitos tokenizados, jun-2026)", "valor": "https://www.theclearinghouse.org/payment-systems/Articles/2026/06/Major-Financial-Institutions-Unveil-Bank-Led-On-Chain-Money-Initiative", "fuente": "https://www.theclearinghouse.org/payment-systems/Articles/2026/06/Major-Financial-Institutions-Unveil-Bank-Led-On-Chain-Money-Initiative"}, {"canal": "Cobertura independiente del anuncio TCH (cita de Mark Monaco)", "valor": "https://www.marketsmedia.com/u-s-banks-unveil-onchain-money-initiative/", "fuente": "https://www.marketsmedia.com/u-s-banks-unveil-onchain-money-initiative/"}, {"canal": "LinkedIn página de empresa", "valor": "https://www.linkedin.com/company/bank-of-america", "fuente": "https://www.linkedin.com/company/bank-of-america"}, {"canal": "X / Twitter", "valor": "@BankofAmerica", "fuente": "https://x.com/BankofAmerica"}, {"canal": "Formulario de partnerships / página de la unidad de activos digitales", "valor": null, "fuente": "https://newsroom.bankofamerica.com/content/newsroom/journalist-resources/bank-of-america-media-contacts"}]'::jsonb, ruta_recomendada='1) Email inicial a Sonali Theisen (Head of Global Digital Assets Platform, NY) con CC a Adam Dixon (Global Head of Digital Asset Transformation, Londres): proponer cross-listing/distribución secundaria de productos tokenizados de BofA en Centroamérica vía Kabal Digital Marketplace (PSAD-0056) y liquidez ancla para emisiones RWA. 2) Si no hay respuesta en 7-10 días, segunda vía por Global Payments Solutions: Mark Monaco (vocero de BofA en el consorcio TCH de depósitos tokenizados) y Annali Duarte (GPS Latinoamérica) con ángulo de pagos/depósitos tokenizados para corredores Centroamérica-EE. UU. 3) Intro cálida: The Clearing House (consorcio de depósitos tokenizados) o socios comunes como Chainlink, Circle o Securitize; Gabriel Andrade (GPS México) como puente regional. 4) Fallback: InMail de LinkedIn a Theisen/Dixon y contactos del newsroom (direcciones públicas @bofa.com) para que deriven a la unidad de activos digitales.',
 decisor=coalesce('Sonali Theisen — Head of Global Digital Assets Platform (desde jul-2026); mantiene Global Head of FICC Electronic Trading & Markets Strategic Investments',decisor), contacto_email=coalesce(contacto_email,null),
 notas=coalesce(notas,'')||E'\n[Contactos '||to_char(now(),'YYYY-MM-DD')||'] Programa: '||'Miembro del consorcio de depósitos tokenizados de The Clearing House; planes públicos de stablecoin/tokenización 2025-2026.'||E'\n'||'Investigación automática 2026-10-19 (lote EXPLORE 2 del Liquidity Agent): agente de búsqueda + verificación adversarial de roles y correos; 12 búsquedas. Todo correo con patron_no_verificado debe confirmarse antes de enviar.'
where id=(select id from p);
insert into liq_contactos (proveedor_id,nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
select (select id from liq_proveedores where nombre='Bank of America'), v.* from (values
('Sonali Theisen','Head of Global Digital Assets Platform (desde jul-2026); mantiene Global Head of FICC Electronic Trading & Markets Strategic Investments','Global Markets / Digital Assets Platform','Nueva York, EE. UU.',null,'sonali.theisen@bofa.com','patron_no_verificado','dueno_programa',1,'Nombrada el 17-jul-2026 (memo interno reportado por Reuters/Bloomberg) para diseñar, construir, escalar y gobernar la plataforma global de activos digitales (stablecoins, depósitos tokenizados, custodia, liquidación cripto), integrando productos blockchain en la infraestructura de mercados del banco. Es la cabeza del producto tokenizado y quien evaluaría distribución/cross-listing.','https://www.theblock.co/post/408830/bank-of-america-taps-new-leaders-bridge-crypto-ai-traditional-finance','Verificación: rol confirmado en 2026 por múltiples fuentes (The Block, Bloomberg Law, Crowdfund Insider 2026/07/292449, East & Partners); trabaja en coordinación con Adam Dixon. La URL original de Crowdfund Insider (292621) no apareció en ninguna búsqueda y no pudo abrirse (sin salida HTTP en el entorno), por lo que se sustituyó por la de The Block, que sí figura en resultados. Ubicación NY no reconfirmada en esta pasada (se infiere de su rol FICC). Email derivado del patrón nombre.apellido@bofa.com (patrón respaldado por direcciones públicas del newsroom; dirección exacta no publicada). LinkedIn no localizado.'),
('Adam Dixon','Global Head of Digital Asset Transformation','Digital Assets / Estrategia empresarial','Londres, Reino Unido',null,'adam.dixon@bofa.com','patron_no_verificado','decisor',2,'Nombrado el 2-jun-2026 (memo reportado por Bloomberg); coordina cripto, tokenización y blockchain de todo el banco (depósitos tokenizados, stablecoins, colateral digital, liquidación y custodia), unificando esfuerzos antes dispersos entre trading, mercados y tecnología. Puede patrocinar una alianza con un venue regulado en LatAm.','https://eastandpartners.com/news/bank-of-america-appoints-adam-dixon-as-global-head-of-digital-asset-transformation/','Verificación: rol, fecha (jun-2026), sede Londres, 20+ años en el banco y cargo previo (Head of Global Markets Financial Resource Management) confirmados por Bloomberg Law, East & Partners, Crypto Briefing y Crowdfund Insider. La URL original de news.bitcoin.com no apareció en búsquedas ni pudo abrirse; se sustituyó por la de East & Partners, que sí figura en resultados. Línea de reporte a Bernie Mensah / Thong Nguyen proviene de la investigación original y no se reconfirmó. Email derivado del patrón nombre.apellido@bofa.com (dirección exacta no publicada). Poner en CC del primer correo.'),
('Mark Monaco','Head of Global Payments Solutions','Global Payments Solutions (GPS)','EE. UU.',null,'mark.monaco@bofa.com','patron_no_verificado','influencer',3,'Vocero de BofA en el anuncio de jun-2026 de The Clearing House sobre la red bancaria de depósitos tokenizados (JPMorgan, Citi, Wells Fargo, BofA; red prevista para 2027); GPS es la unidad que integra el consorcio y la vía natural para pagos/liquidación tokenizada hacia Centroamérica.','https://www.marketsmedia.com/u-s-banks-unveil-onchain-money-initiative/','Verificación: cargo y cita textual ("Bank of America sees significant potential for tokenization, including tokenized deposits...") confirmados en cobertura de jun-2026 (Markets Media, The Defiant, Unchained, Green Sheet). La URL de The Clearing House citada originalmente no apareció en resultados de búsqueda y no pudo abrirse; se sustituyó como fuente por Markets Media (sí figura en resultados) y se mantiene la de TCH en canales_publicos. El reconocimiento de The Asian Banker 2026 mencionado originalmente NO se reverificó. Email derivado del patrón nombre.apellido@bofa.com (dirección exacta no publicada).'),
('Annali Duarte','Head of Global Payments Solutions, Latin America','Global Payments Solutions - Latinoamérica','No confirmada (cobertura Latinoamérica)',null,'annali.duarte@bofa.com','patron_no_verificado','cobertura_latam',4,'Lidera GPS para Latinoamérica (estrategia regional de transaction banking: pagos, cobros, liquidez, trade y supply chain finance para grandes corporativos e instituciones financieras); es el punto de cobertura regional más cercano a Centroamérica dentro de la unidad que participa en el consorcio de depósitos tokenizados.','https://eastandpartners.com/news/bank-of-america-strengthens-global-payments-solutions-leadership-in-apac-and-mexico/','Verificación: rol respaldado por East & Partners (2025), por su ficha en el LATAM Advisory Board de Women in Payments y por un perfil de ponente en AS/COA (más antiguo, con la denominación previa GTS). No se encontró confirmación fechada en 2026; validar en LinkedIn antes de enviar. Email derivado del patrón nombre.apellido@bofa.com (dirección exacta no publicada).'),
('Gabriel Andrade','Managing Director, Head of Global Payments Solutions, México','Global Payments Solutions - México','Ciudad de México, México',null,'gabriel.andrade@bofa.com','patron_no_verificado','cobertura_latam',5,'Responsable de GPS en México (reporta a Annali Duarte); puente regional alterno para una intro cálida hacia la unidad de activos digitales y para corredores México-Centroamérica.','https://eastandpartners.com/news/bank-of-america-strengthens-global-payments-solutions-leadership-in-apac-and-mexico/','Verificación: se incorporó al banco en feb-2025 como líder de GPS en Ciudad de México (anuncio público abr-2025; corregida la fecha original que indicaba nombramiento en abril). Confirmado por East & Partners, GTR, Treasury Management International y The Asian Banker. La mención de un listado CFO Forum 2026 no se reverificó. Email derivado del patrón nombre.apellido@bofa.com (dirección exacta no publicada).')) as v(nombre,cargo,area,ubicacion,linkedin,email,email_estado,rol,prioridad,por_que,fuente,notas)
on conflict (proveedor_id, lower(nombre)) do update set cargo=excluded.cargo, area=excluded.area, ubicacion=excluded.ubicacion,
 linkedin=coalesce(excluded.linkedin,liq_contactos.linkedin), email=coalesce(excluded.email,liq_contactos.email), email_estado=excluded.email_estado,
 rol=excluded.rol, prioridad=excluded.prioridad, por_que=excluded.por_que, fuente=excluded.fuente, notas=excluded.notas;
